        let plain = unpack__m512i_to_i8_array(_mm512_shuffle_epi8(a, b));
        let src_lanes = unpack__m512i_to_i8_array(src);
        let expected: [i8; 64] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm512_mask_shuffle_epi8(src, k, a, b) vs _mm512_shuffle_epi8(a, b)"))?;
